import{_ as e,o as l,a as o,b as d}from"./app.UgfkfLuP.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"HCCL通信类","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_communication"},{"text":"HCCL Tiling侧接口","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/HCCL_Tiling"},{"text":"SetAlgConfig","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetAlgConfig"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetAlgConfig.md","filePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetAlgConfig.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793014501000}'),h={name:"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetAlgConfig.md"};function a(c,t,r,s,n,i){return l(),o("div",null,[...t[0]||(t[0]=[d(`<div><article class="markdown-body"><h1>SetAlgConfig</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>设置通信算法。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>uint32_t SetAlgConfig(const std::string&amp; algConfig)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>algConfig</td><td>输入</td><td>通信算法配置。string类型，支持的最大长度为128字节。不指定（置空或传入&quot;default&quot;）时通信库根据组网拓扑自动选择算法，推荐优先使用该方式。<span data-filter="950"><br><br>针对Ascend 950PR&amp;950DT系列产品，当前支持的取值如下，具体含义请参考下方说明：<br>AllGather通信任务（AI CPU服务端）：&quot;sole[mesh]&quot;、&quot;sole[nhr]&quot;、&quot;sole[nhr.multi_channel]&quot;、&quot;sequence[mesh,nhr]&quot;、&quot;concur[mesh,nhr]&quot;、&quot;parallel[mesh,nhr]&quot;、&quot;parallel[mesh,nhr.multi_channel]&quot;、&quot;pipeline[mesh,nhr]&quot;。<br>AllGather通信任务（CCU服务端）：&quot;sole[mesh]&quot;、&quot;sole[nhr]&quot;、&quot;concur[mesh,nhr.multi_channel]&quot;、&quot;parallel[mesh,nhr.multi_channel]&quot;。<br>ReduceScatter通信任务（AI CPU服务端）：&quot;sole[mesh]&quot;、&quot;sole[mesh.chunk]&quot;、&quot;sole[nhr]&quot;、&quot;sole[nhr.multi_channel]&quot;、&quot;sequence[mesh,nhr]&quot;、&quot;parallel[mesh,nhr]&quot;、&quot;concur[mesh,nhr]&quot;、&quot;pipeline[mesh,nhr]&quot;。<br>ReduceScatter通信任务（CCU服务端）：&quot;sole[mesh]&quot;、&quot;sole[nhr]&quot;、&quot;sole[nhr.multi_channel]&quot;、&quot;concur[mesh,nhr.multi_channel]&quot;。<br>AllReduce通信任务（AI CPU服务端）：&quot;sole[mesh.one_shot]&quot;、&quot;sole[mesh.two_shot]&quot;、&quot;sole[mesh.two_shot.chunk]&quot;、&quot;sole[nhr]&quot;、&quot;parallel[mesh,nhr]&quot;、&quot;pipeline[mesh,nhr]&quot;。<br>AllReduce通信任务（CCU服务端）：&quot;sole[mesh]&quot;。<br>AlltoAll通信任务（AI CPU服务端）：&quot;sole[mesh]&quot;、&quot;sole[mesh.single_channel]&quot;、&quot;concur[mesh,mesh]&quot;。<br>AlltoAll通信任务（CCU服务端）：&quot;sole[mesh]&quot;、&quot;sole[mesh.multi_channel]&quot;、&quot;concur[mesh,mesh]&quot;。<br>AlltoAllV通信任务（AI CPU服务端）：&quot;sole[mesh]&quot;、&quot;concur[mesh,mesh]&quot;。<br>AlltoAllV通信任务（CCU服务端）：&quot;sole[mesh]&quot;。</span><span data-filter="A3"><br><br>针对Atlas A3系列产品，当前支持的取值为：<br>&quot;AllReduce=level0:doublering&quot;：AllReduce通信任务。<br>&quot;AllGather=level0:doublering&quot;：AllGather通信任务。<br>&quot;ReduceScatter=level0:doublering&quot;：ReduceScatter通信任务。<br>&quot;AlltoAll=level0:fullmesh;level1:pairwise&quot;：AlltoAllV和AlltoAll通信任务。<br>&quot;BatchWrite=level0:fullmesh&quot;：BatchWrite通信任务。</span><span data-filter="910b"><br><br>针对Atlas A2系列产品，该参数为预留字段，配置后不生效，默认仅支持FullMesh算法。FullMesh算法即NPU之间的全连接，任意两个NPU之间可以直接进行数据收发。</span></td></tr></tbody></table><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品，算法配置字段详细说明如下：</p><ol><li><p>语法</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>编排方式[&lt;域内遍历方式&gt;(.&lt;附加属性&gt;)*,&lt;域内遍历方式&gt;(.&lt;附加属性&gt;)*,...]
</code></pre></div><p>示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>sole[mesh]
concur[mesh,mesh]
parallel[mesh,nhr.multi_channel]
</code></pre></div><table><thead><tr><th>字段</th><th>含义</th><th>是否必填</th></tr></thead><tbody><tr><td><code>编排方式</code></td><td>各域之间的流水关系</td><td>必填</td></tr><tr><td><code>&lt;域内遍历方式&gt;</code></td><td><code>[]</code>中的多个取值按通信层级从低到高排列</td><td>至少一个</td></tr><tr><td><code>.&lt;附加属性&gt;</code></td><td>该层的附加功能属性</td><td>可选</td></tr></tbody></table><p>通信算法配置末尾支持可选的算子级保序后缀<code>[order.strong]</code>，如<code>sole[mesh] [order.strong]</code>。当前版本该后缀仅被校验与记录，不影响算法选定结果。</p></li><li><p>编排方式</p><table><thead><tr><th>取值</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td><code>sole</code></td><td>在单个域内完成通信</td><td><code>sole[mesh]</code></td></tr><tr><td><code>sequence</code></td><td>多域按序串行执行，前一域的输出作为后一域的输入</td><td><code>sequence[mesh,nhr]</code></td></tr><tr><td><code>parallel</code></td><td>多域并行执行，各域互不依赖</td><td><code>parallel[mesh,nhr]</code></td></tr><tr><td><code>concur</code></td><td>同一份数据切分为两份，两域并发处理，每域处理一份数据</td><td><code>concur[mesh,nhr]</code>、<code>concur[mesh,mesh]</code></td></tr><tr><td><code>pipeline</code></td><td>多批次流水编排，数据划分为多个批次，第1批数据在域A传输的同时，第2批数据已在域B传输</td><td><code>pipeline[mesh,nhr]</code></td></tr></tbody></table></li><li><p>域内遍历方式与附加属性</p><p>域内遍历方式：</p><table><thead><tr><th>域内遍历方式</th><th>含义</th></tr></thead><tbody><tr><td><code>mesh</code></td><td>1D Fullmesh</td></tr><tr><td><code>nhr</code></td><td>非均衡层次环</td></tr></tbody></table><p>外部可配置的附加属性：</p><table><thead><tr><th>取值</th><th>功能类别</th><th>含义</th></tr></thead><tbody><tr><td><code>mesh.chunk</code></td><td>传输</td><td>将数据划分为多个chunk分轮传输</td></tr><tr><td><code>mesh.one_shot</code></td><td>编排</td><td>一趟Mesh通信完成AllReduce</td></tr><tr><td><code>mesh.two_shot</code></td><td>编排</td><td>同层先执行ReduceScatter，再执行AllGather</td></tr><tr><td><code>mesh.multi_channel</code></td><td>通道</td><td>Mesh域内每对rank之间建立多条物理通道并发传输数据</td></tr><tr><td><code>mesh.single_channel</code></td><td>通道</td><td>每对rank之间仅建立1条通道传输数据</td></tr><tr><td><code>nhr.multi_channel</code></td><td>通道</td><td>NHR域内每对rank之间建立多条物理通道并发传输数据</td></tr></tbody></table></li><li><p>配置指导</p><ul><li><p>不指定算法（推荐）</p><p>将<code>algConfig</code>置空或传入<code>&quot;default&quot;</code>，通信库根据实际组网拓扑自动选择算法。用户无需了解机型拓扑细节，该方式在多数场景下即可获得较优性能，建议作为首选。</p></li><li><p>域内遍历方式由数据传播特性与物理组网共同决定</p><p>需要显式指定算法时，用户能明确的是物理组网方式（即通信域内任意两卡之间是否存在直连通路）。域内遍历方式代表通信算法在当前通信域内如何使用这些链路，它由通信原语的数据传播特性与物理组网共同决定：</p><ul><li><code>mesh</code>（直连遍历）：链路直达目的卡。适用于数据块按目的卡独立切分、无需跨卡接力传播的场景（AlltoAll、AlltoAllV属此类，任何组网下均适用）；数据沿卡逐级放大或收缩的原语在Mesh组网下也用直连遍历。</li><li><code>nhr</code>（非均衡层次环遍历）：数据沿环逐卡接力传播，适用于数据需要跨卡接力放大或收缩的原语（如AllGather、ReduceScatter），且仅在CLOS组网（经交换芯片互连、非全直连）下有收益。</li><li>混合组网（如机内Mesh直连+机间经交换芯片互连）：<code>[]</code>中按level0-&gt;level1从低到高逐层指定，最多支持两个通信域，例如双层组网下AllGather使用<code>parallel[mesh,nhr]</code>。</li></ul><p>一句话总结：AlltoAll、AlltoAllV配置为mesh；AllGather、ReduceScatter在Mesh组网配置为mesh、CLOS组网配置为nhr；AllReduce在CCU服务端仅支持mesh遍历，AI CPU服务端还支持含nhr层的取值。各通信任务在各服务端实际可用的取值以上方参数说明中的列表为准。</p></li><li><p>编排方式与附加属性的选择</p><p>确定各域的遍历方式后，剩余字段按以下方式确定：</p><ul><li><code>编排方式</code>：先确认当前取值列表中是否有可选项。仅一个可选项时（如AllReduce CCU服务端的<code>sole</code>）直接使用；有多个可选项时（如AllGather的<code>sole</code>与<code>parallel</code>），结合实测性能benchmark曲线和业务数据量确定。</li><li><code>附加属性</code>：每层的可选属性以取值列表中该层实际列出的为准。列表未列出某属性（如AllGather CCU服务端的mesh层无<code>multi_channel</code>）即表示当前版本该层不支持，无需尝试。</li></ul></li><li><p>配置错误处理</p><p>指定了当前版本不支持的算法配置（语法错误、未注册的算法名等）时，指定算法失败，优先回退到内置自动选择算法，若当前版本不支持该机型则报错退出。</p></li></ul></li></ol></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><ul><li>0表示设置成功。</li><li>非0表示设置失败。</li></ul><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><ul><li>对于Ascend 950PR&amp;950DT系列产品，通信算法配置需与当前通信服务端类型及组网拓扑匹配，方可解析为唯一算法。无法解析时，AI CPU服务端将打印WARNING日志并回退至自动选路；CCU服务端将报算法不支持。</li></ul></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>本接口的调用示例请见<a href="SetOpType.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">调用示例</a>。</p></article></div>`,1)])])}const m=e(h,[["render",a]]);export{p as __pageData,m as default};
